                let result: Result<(usize, SocketAddr), Error> = match select(recv, &mut cancelled).await {
                    Either::Left((left: Result<(usize, SocketAddr), Error>, _)) => left,
                    Either::Right(_) => break,
                };

                let len: usize = match result {
                    Ok((0, _)) => continue,
                    Ok((len: usize, _)) => len,
                    Err(e: Error) => {
                        tracing::warn!("failed to receive data: {e}");
                        continue;
                    }
                };

                let mut buffer: Vec<u8> = match buffer.take() {
                    Some(mut buffer: Vec<u8>) => {
                        // SAFETY: at this point we have initialized at least `len` bytes of partially
                        // initialized data of len `RECV_BUFFER_SIZE`
                        unsafe { buffer.set_len(len) };
                        buffer
                    }
                    None => continue,
                };

                // Process packet
                let ctx: Arc<ReceiverContext> = ctx.clone();
                tokio::spawn(async move {
                    if let Err(error: Error) = ctx
                        .node
                        .handle_received_data(
                            PacketView::from(buffer.as_mut_slice()),
                            &ctx.message_subscribers,
                            &ctx.query_subscribers,
                        )
                        .await
                    {
                        tracing::trace!(?error, "failed to handle received data");
                    }
                });
            }

            tracing::debug!("receiver loop finished");
        });
    }

